class Solution {
public:
    int maximumsSplicedArray(vector<int>& nums1, vector<int>& nums2) {
        long long s1 = 0, s2 = 0;
        int n = nums1.size();
        for (int i = 0; i < n; i++) {
            s1 += nums1[i];
            s2 += nums2[i];
        }
        long long best1 = 0, cur1 = 0;
        long long best2 = 0, cur2 = 0;
        for (int i = 0; i < n; i++) {
            long long d1 = (long long)nums2[i] - nums1[i];
            long long d2 = (long long)nums1[i] - nums2[i];
            cur1 = max(d1, cur1 + d1);
            best1 = max(best1, cur1);
            cur2 = max(d2, cur2 + d2);
            best2 = max(best2, cur2);
        }
        long long ans = max(s1 + best1, s2 + best2);
        return (int)ans;
    }
};
